    public static func withTables<R>(_ body: (Span<UInt8>, Span<UInt32>, Span<UInt16>, Span<UInt32>, Span<UInt32>) -> R) -> R {
        body(pool.span, keys.span, keyValues.span, valueStarts.span, words.span)
